/**
 * FORMA Video Editor — Full 17x17x17 3D LUT Generator
 * Replaces any 2x2x2 stubs with authentic 17x17x17 (4,913 points) 3D .CUBE files
 * with genuine mathematical color grading matrices per category.
 */

import fs from 'fs';
import path from 'path';

const LUTS_DIR = path.join(process.cwd(), 'public', 'video-assets', 'luts');
fs.mkdirSync(LUTS_DIR, { recursive: true });

const SIZE = 17; // 17x17x17 = 4,913 data points

function generate3DCube(spec) {
  const lines = [
    `TITLE "${spec.name}"`,
    `LUT_3D_SIZE ${SIZE}`,
    '# Generated by Forma Color Engine — Creative Commons Zero (CC0)',
    'DOMAIN_MIN 0.0 0.0 0.0',
    'DOMAIN_MAX 1.0 1.0 1.0',
  ];

  for (let b = 0; b < SIZE; b++) {
    for (let g = 0; g < SIZE; g++) {
      for (let r = 0; r < SIZE; r++) {
        let rNorm = r / (SIZE - 1);
        let gNorm = g / (SIZE - 1);
        let bNorm = b / (SIZE - 1);

        // 1. Contrast adjustment
        if (spec.contrast !== 1.0) {
          const c = spec.contrast;
          rNorm = Math.max(0, Math.min(1, (rNorm - 0.5) * c + 0.5));
          gNorm = Math.max(0, Math.min(1, (gNorm - 0.5) * c + 0.5));
          bNorm = Math.max(0, Math.min(1, (bNorm - 0.5) * c + 0.5));
        }

        // 2. Channel multipliers & balance
        rNorm = Math.max(0, Math.min(1, rNorm * spec.rBias));
        gNorm = Math.max(0, Math.min(1, gNorm * spec.gBias));
        bNorm = Math.max(0, Math.min(1, bNorm * spec.bBias));

        // 3. Lift / Gamma / Gain emulation
        if (spec.shadowTint) {
          // Push tint into shadows
          const shadowFactor = Math.pow(1 - (rNorm + gNorm + bNorm) / 3, 2);
          rNorm = Math.min(1, rNorm + spec.shadowTint.r * shadowFactor * 0.15);
          gNorm = Math.min(1, gNorm + spec.shadowTint.g * shadowFactor * 0.15);
          bNorm = Math.min(1, bNorm + spec.shadowTint.b * shadowFactor * 0.15);
        }

        if (spec.highlightTint) {
          // Push tint into highlights
          const highFactor = Math.pow((rNorm + gNorm + bNorm) / 3, 2);
          rNorm = Math.min(1, rNorm + spec.highlightTint.r * highFactor * 0.15);
          gNorm = Math.min(1, gNorm + spec.highlightTint.g * highFactor * 0.15);
          bNorm = Math.min(1, bNorm + spec.highlightTint.b * highFactor * 0.15);
        }

        // 4. Saturation adjustment
        if (spec.saturation !== 1.0) {
          const luma = 0.2126 * rNorm + 0.7152 * gNorm + 0.0722 * bNorm;
          rNorm = Math.max(0, Math.min(1, luma + (rNorm - luma) * spec.saturation));
          gNorm = Math.max(0, Math.min(1, luma + (gNorm - luma) * spec.saturation));
          bNorm = Math.max(0, Math.min(1, luma + (bNorm - luma) * spec.saturation));
        }

        lines.push(`${rNorm.toFixed(6)} ${gNorm.toFixed(6)} ${bNorm.toFixed(6)}`);
      }
    }
  }

  return lines.join('\n');
}

const CATEGORIES = [
  {
    prefix: 'cinema',
    count: 20,
    titlePrefix: 'Sinematik Gişe',
    base: { rBias: 1.12, gBias: 1.02, bBias: 0.94, contrast: 1.18, saturation: 1.1, shadowTint: { r: 0.0, g: 0.3, b: 0.7 }, highlightTint: { r: 1.0, g: 0.6, b: 0.1 } }
  },
  {
    prefix: 'film',
    count: 20,
    titlePrefix: 'Analog Film',
    base: { rBias: 1.08, gBias: 1.04, bBias: 0.96, contrast: 1.1, saturation: 0.92, shadowTint: { r: 0.2, g: 0.2, b: 0.3 }, highlightTint: { r: 0.8, g: 0.7, b: 0.5 } }
  },
  {
    prefix: 'vlog',
    count: 20,
    titlePrefix: 'Vlog & Canlı',
    base: { rBias: 1.06, gBias: 1.05, bBias: 1.02, contrast: 1.14, saturation: 1.22, shadowTint: { r: 0.0, g: 0.0, b: 0.0 }, highlightTint: { r: 0.4, g: 0.3, b: 0.1 } }
  },
  {
    prefix: 'nature',
    count: 20,
    titlePrefix: 'Doğa & Manzara',
    base: { rBias: 0.98, gBias: 1.15, bBias: 1.08, contrast: 1.16, saturation: 1.25, shadowTint: { r: 0.1, g: 0.3, b: 0.2 }, highlightTint: { r: 0.5, g: 0.7, b: 0.3 } }
  },
  {
    prefix: 'artistic',
    count: 20,
    titlePrefix: 'Sanatsal & Stilize',
    base: { rBias: 1.25, gBias: 0.92, bBias: 1.18, contrast: 1.22, saturation: 1.15, shadowTint: { r: 0.4, g: 0.1, b: 0.5 }, highlightTint: { r: 0.9, g: 0.3, b: 0.7 } }
  },
  {
    prefix: 'commercial',
    count: 20,
    titlePrefix: 'Ticari & Reklam',
    base: { rBias: 1.04, gBias: 1.04, bBias: 1.04, contrast: 1.12, saturation: 1.08, shadowTint: { r: 0.0, g: 0.0, b: 0.0 }, highlightTint: { r: 0.1, g: 0.1, b: 0.1 } }
  },
];

console.log('[LUT Generator] Generating 120 authentic 17x17x17 3D LUTs...');
let generatedCount = 0;

for (const cat of CATEGORIES) {
  for (let i = 1; i <= cat.count; i++) {
    const pad = i.toString().padStart(3, '0');
    const filename = `${cat.prefix}-${pad}.cube`;
    const fullPath = path.join(LUTS_DIR, filename);

    // Minor variations per preset
    const factor = (i - 1) / 20;
    const spec = {
      name: `${cat.titlePrefix} #${i}`,
      rBias: cat.base.rBias + (factor * 0.1 - 0.05),
      gBias: cat.base.gBias + (factor * 0.06 - 0.03),
      bBias: cat.base.bBias + (factor * 0.08 - 0.04),
      contrast: cat.base.contrast + (factor * 0.1 - 0.05),
      saturation: cat.base.saturation + (factor * 0.15 - 0.07),
      shadowTint: cat.base.shadowTint,
      highlightTint: cat.base.highlightTint,
    };

    const cubeContent = generate3DCube(spec);
    fs.writeFileSync(fullPath, cubeContent, 'utf-8');
    generatedCount++;
  }
}

console.log(`[LUT Generator] Generated ${generatedCount} full 17x17x17 3D LUTs (each ~132 KB).`);
